// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint16 numCalls) public {
        vm.assume(numCalls > 0 && numCalls <= 100);
        uint256 bankBefore = address(c.bank()).balance;
        address player = address(0x1234);
        for (uint16 i = 0; i < numCalls; i++) {
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }
        uint256 bankAfter = address(c.bank()).balance;
        uint256 totalFees = bankAfter - bankBefore;
        uint256 contractBalance = address(c).balance;
        assertTrue(contractBalance == c.pot() + totalFees);
    }
}
